import { LOGO } from "./orbitLogoGeometry";

/**
 * The Orbit logo as React: a mark (planet, a ring that passes behind it above and in front of it below, one satellite)
 * and a wordmark of five custom capitals. The numbers come from `orbitLogoGeometry.ts`, generated by
 * `docs/brand/build_logo.py` together with the master files in `public/brand/` - see `docs/brand/README.md` for the
 * rules of use (clear space, minimum size, colours).
 *
 * The same drawing serves the static logo (header, forgot-password, invitation) and the animated one on the landing
 * page, so the animation always ends on exactly the logo everyone else sees. Colours are CSS variables
 * (`--logo-*`, see globals.css) so the logo follows the theme; the shapes use SVG masks for the knock-outs, so there is
 * no background colour baked in and the logo sits on any surface.
 */
export { LOGO };

/** Width / height of the lockup. */
export const LOGO_ASPECT = LOGO.width / LOGO.height;

/** The height that goes with a width, so the logo is never stretched. */
export function logoHeightFor(width: number): number {
  return Math.round((width / LOGO_ASPECT) * 100) / 100;
}

/** Margin around the mark inside the masks, so a mask never clips the drawing it cuts. */
const MASK_MARGIN = 10;

/** The planet's gradient and the two masks that make the knock-outs. Render once per logo, with a unique `id`. */
export function OrbitLogoDefs({ id }: { id: string }) {
  const { planet, ring, satellite, gap } = LOGO;
  const region = {
    maskUnits: "userSpaceOnUse" as const,
    x: -MASK_MARGIN,
    y: -MASK_MARGIN,
    width: LOGO.width + 2 * MASK_MARGIN,
    height: LOGO.height + 2 * MASK_MARGIN,
  };
  return (
    <defs>
      <linearGradient
        id={`${id}-planet`}
        gradientUnits="userSpaceOnUse"
        x1={planet.cx - planet.r}
        y1={planet.cy - planet.r}
        x2={planet.cx + planet.r}
        y2={planet.cy + planet.r}
      >
        <stop offset="0" style={{ stopColor: "var(--logo-planet-from)" }} />
        <stop offset="1" style={{ stopColor: "var(--logo-planet-to)" }} />
      </linearGradient>
      {/* The planet is cut away around the part of the ring that passes in front of it. */}
      <mask id={`${id}-planet-cut`} {...region}>
        <rect x={region.x} y={region.y} width={region.width} height={region.height} fill="#fff" />
        <path d={ring.front} fill="none" stroke="#000" strokeWidth={ring.strokeWidth + 2 * gap} />
      </mask>
      {/* The ring is cut away around the satellite. */}
      <mask id={`${id}-ring-cut`} {...region}>
        <rect x={region.x} y={region.y} width={region.width} height={region.height} fill="#fff" />
        <circle cx={satellite.cx} cy={satellite.cy} r={satellite.r + gap} fill="#000" />
      </mask>
    </defs>
  );
}

/** The mark: whole ring behind, planet (cut where the ring crosses it), the front half of the ring again, satellite. */
export function OrbitLogoMark({ id }: { id: string }) {
  const { planet, ring, satellite } = LOGO;
  return (
    <>
      <ellipse
        className="orbit-logo-ring"
        cx={ring.cx}
        cy={ring.cy}
        rx={ring.rx}
        ry={ring.ry}
        transform={`rotate(${ring.tilt} ${ring.cx} ${ring.cy})`}
        fill="none"
        strokeWidth={ring.strokeWidth}
        mask={`url(#${id}-ring-cut)`}
      />
      <circle
        cx={planet.cx}
        cy={planet.cy}
        r={planet.r}
        fill={`url(#${id}-planet)`}
        mask={`url(#${id}-planet-cut)`}
      />
      <path className="orbit-logo-ring" d={ring.front} fill="none" strokeWidth={ring.strokeWidth} />
      <circle className="orbit-logo-satellite" cx={satellite.cx} cy={satellite.cy} r={satellite.r} />
    </>
  );
}

/** The five capitals in their places in the lockup. */
export function OrbitWord() {
  return (
    <g className="orbit-logo-word">
      {LOGO.letters.map((letter) => (
        <path key={letter.char} transform={`translate(${letter.x} ${letter.y})`} d={letter.d} />
      ))}
    </g>
  );
}
